import{$ as e,A as t,B as n,V as r}from"./chunks/framework.Civ1omIV.js";var i=JSON.parse(`{"title":"Hako","description":"Hako is an open-source mihomo fork for Apple NetworkExtension, providing Clash with multi-protocol routing, DNS, policy groups, and local control.","frontmatter":{"title":"Hako","description":"Hako is an open-source mihomo fork for Apple NetworkExtension, providing Clash with multi-protocol routing, DNS, policy groups, and local control.","keywords":["Hako core","mihomo iOS core","NetworkExtension proxy core","open-source network core","Hako xcframework"],"jsonLd":{"@context":"https://schema.org","@type":"SoftwareSourceCode","name":"Hako","description":"An open-source mihomo fork for Apple NetworkExtension that provides Clash with multi-protocol, rule-based routing.","codeRepository":"https://github.com/TokenPLS/Hako","license":"https://www.gnu.org/licenses/gpl-3.0.html","programmingLanguage":"Go","runtimePlatform":["iOS","iPadOS","macOS","tvOS"],"isBasedOn":"https://github.com/MetaCubeX/mihomo","inLanguage":"en-US"}},"headers":[],"relativePath":"hako.md","filePath":"hako.md","lastUpdated":1785318168000}`),a={name:`hako.md`};function o(t,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[r(`<h1 id="hako" tabindex="-1">Hako <a class="header-anchor" href="#hako" aria-label="Permalink to “Hako”">​</a></h1><p><strong>High-performance Adaptive Kernel — Open-source</strong></p><p>Hako is the open-source networking core that powers Clash. It packages a stable fork of <a href="https://github.com/MetaCubeX/mihomo" target="_blank" rel="noreferrer">mihomo</a> as <code>Hako.xcframework</code>, with Swift and Objective-C interfaces for Apple apps.</p><h2 id="built-for-apple-platforms" tabindex="-1">Built for Apple platforms <a class="header-anchor" href="#built-for-apple-platforms" aria-label="Permalink to “Built for Apple platforms”">​</a></h2><p>Clash runs Hako inside Apple&#39;s NetworkExtension environment. Packet transport uses the public <code>NEPacketTunnelFlow</code> API throughout, following Apple&#39;s public system interfaces.</p><p>The core is tuned for the memory and energy goals of packet tunnel extensions. It exposes local runtime state—throughput, connections, memory and health—so the app can show what the core is doing.</p><h2 id="measured-on-real-hardware" tabindex="-1">Measured on real hardware <a class="header-anchor" href="#measured-on-real-hardware" aria-label="Permalink to “Measured on real hardware”">​</a></h2><p>The public Hako release evidence includes controlled tests on an iPad Pro (M2):</p><table tabindex="0"><thead><tr><th>Test</th><th>Result</th></tr></thead><tbody><tr><td>Public-network Speedtest</td><td>924 Mbps down · 545 Mbps up · 5 ms latency</td></tr><tr><td>Core memory during that test</td><td>18.7 MiB</td></tr><tr><td>30-minute pressure run</td><td>16.49 GB transferred · 0 disconnects · 0 packet loss · 0 crashes</td></tr><tr><td>400 concurrent connections</td><td>39.6 MiB under a 50 MiB test budget</td></tr></tbody></table><p>These figures record the measured result for the specified hardware, network, and build. Performance varies with device, route, and configuration.</p><h2 id="what-the-core-provides" tabindex="-1">What the core provides <a class="header-anchor" href="#what-the-core-provides" aria-label="Permalink to “What the core provides”">​</a></h2><ul><li><strong>Protocols:</strong> Shadowsocks, VMess, VLESS, Trojan, Snell, Hysteria, Hysteria2, TUIC, WireGuard, AnyTLS, SSH and more.</li><li><strong>DNS:</strong> DoH, DoT, DoQ, fake-IP, traffic sniffing and per-domain resolver rules.</li><li><strong>Routing:</strong> domain, IP-CIDR, GEOIP, GEOSITE, RULE-SET and logical rules.</li><li><strong>Policy groups:</strong> select, url-test, fallback and load-balance, including health checks and remote providers.</li><li><strong>Local control:</strong> status, traffic, connections, proxies, logs, latency tests and connection control remain on an app-private local channel.</li></ul><h2 id="open-and-auditable" tabindex="-1">Open and auditable <a class="header-anchor" href="#open-and-auditable" aria-label="Permalink to “Open and auditable”">​</a></h2><p>Hako follows a pinned stable mihomo release. Hako-specific source changes are published under GPL-3.0 for independent review, so every implementation detail and security question can be checked directly against the code.</p><p>The Clash &amp; Hako Team maintains Hako as an independent fork; MetaCubeX and SagerNet are named solely to identify its technical lineage. The SDK uses a pre-1.0 version until the first formal <code>v*-hako.*</code> release.</p><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to “Source”">​</a></h2><ul><li><a href="https://github.com/TokenPLS/Hako" target="_blank" rel="noreferrer">Hako core</a></li><li><a href="https://github.com/TokenPLS/Hako/blob/main/README.md" target="_blank" rel="noreferrer">Complete Hako README</a></li><li><a href="https://github.com/MetaCubeX/mihomo" target="_blank" rel="noreferrer">mihomo upstream</a></li><li><a href="https://github.com/TokenPLS/Hako/blob/main/SECURITY.md" target="_blank" rel="noreferrer">Security policy</a></li></ul>`,17)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};